def is_palindrome(s):
    t=[c.lower() for c in s if c.isalnum()]
    return t==t[::-1]

def two_sum(n,t):
    for i in range(len(n)):
        for j in range(i+1,len(n)):
            if n[i]+n[j]==t: return (i,j)
    return None

def flatten(x):
    o=[]
    for i in x:
        o+= flatten(i) if isinstance(i,list) else [i]
    return o

def valid_parens(s):
    st=[];m={')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{': st.append(c)
        elif not st or st.pop()!=m[c]: return False
    return not st

def max_subarray(a):
    b=c=a[0]
    for x in a[1:]:
        c=max(x,c+x); b=max(b,c)
    return b

def from_roman(s):
    v={'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000};t=0
    for i,c in enumerate(s):
        t+= -v[c] if i+1<len(s) and v[c]<v[s[i+1]] else v[c]
    return t

def collatz_len(n):
    s=0
    while n!=1:
        n= n//2 if n%2==0 else 3*n+1; s+=1
    return s

def word_freq(s):
    d={}
    for w in s.lower().split():
        w=w.strip('.,!?;:')
        if w: d[w]=d.get(w,0)+1
    return d

def dedupe(a):
    s=set();o=[]
    for x in a:
        if x not in s: s.add(x); o.append(x)
    return o

def caesar(s,k):
    o=''
    for c in s:
        if c.isalpha():
            b=65 if c.isupper() else 97
            o+=chr((ord(c)-b+k)%26+b)
        else: o+=c
    return o

def longest_common_prefix(a):
    if not a: return ''
    p=a[0]
    for s in a[1:]:
        while not s.startswith(p): p=p[:-1]
    return p

def gcd_list(a):
    import math
    g=a[0]
    for x in a[1:]: g=math.gcd(g,x)
    return g

def interval_merge(iv):
    o=[]
    for a,b in sorted(iv):
        if o and a<=o[-1][1]: o[-1][1]=max(o[-1][1],b)
        else: o.append([a,b])
    return o

def camel_to_snake(s):
    o=''
    for i,c in enumerate(s):
        if c.isupper() and i>0: o+='_'
        o+=c.lower()
    return o

def lru_sim(keys,cap):
    from collections import OrderedDict
    d=OrderedDict();h=0
    for k in keys:
        if k in d: h+=1; d.move_to_end(k)
        else:
            d[k]=1
            if len(d)>cap: d.popitem(last=False)
    return h

def topo_order(n,e):
    import heapq
    ind=[0]*n;g=[[] for _ in range(n)]
    for u,v in e: g[u].append(v); ind[v]+=1
    h=[i for i in range(n) if ind[i]==0];heapq.heapify(h);o=[]
    while h:
        u=heapq.heappop(h);o.append(u)
        for v in g[u]:
            ind[v]-=1
            if ind[v]==0: heapq.heappush(h,v)
    return o if len(o)==n else None
